package main

import (
	"fmt"
	"time"
)

func sendEmail(name string) {
	time.Sleep(50 * time.Millisecond)
	fmt.Println("sent to", name)
}

func main() {
	names := []string{"ann", "bo", "cy"}
	for _, name := range names {
		go sendEmail(name)
	}
	time.Sleep(time.Second)
}

package main

import "fmt"

func main() {
	ch := make(chan int)
	go func() {
		for v := range ch {
			fmt.Println("got", v)
		}
	}()
	for i := 1; i <= 3; i++ {
		ch <- i
	}
}
